    {
      "tipe": "PASAL",
      "label": "Pasal 11",
      "bagian_dokumen": "BATANG_TUBUH",
      "hierarki": "PASAL",
      "parent_bab": "BAB III",
      "parent_bagian": "Bagian Ketiga",
      "parent_paragraf": "Paragraf 2",
      "parent_pasal_perubahan": "Pasal 18",
      "teks": "Pasal 11 dihapus.",
      "target_induk": "undang-undang-27-2007"
    },
    {
      "tipe": "PASAL",
      "label": "Pasal 12",
      "bagian_dokumen": "BATANG_TUBUH",
      "hierarki": "PASAL",
      "parent_bab": "BAB III",
