    {
      "tipe": "PASAL",
      "label": "Pasal 102",
      "bagian_dokumen": "BATANG_TUBUH",
      "hierarki": "PASAL",
      "parent_bab": "BAB III",
      "parent_bagian": "Bagian Keempat",
      "parent_paragraf": "Paragraf 9 Pekerjaan Umum dan Perumahan Rakyat",
      "parent_pasal_perubahan": "Pasal 69",
      "teks": "Ketentuan Pasal 102 diubah sehingga berbunyi sebagai berikut:\nPasal 102 Ketentuan lebih lanjut mengenai kriteria, jenis, besaran denda, dan tata cara pengenaan sanksi administratif sebagaimana dimaksud dalam Pasal 89, Pasal 90, Pasal 91, Pasal 93, Pasal 94, Pasal 95, Pasal 96, Pasal 97, Pasal 98, Pasal 99, dan Pasal 100 diatur dalam Peraturan Pemerintah.",
      "target_induk": "undang-undang-2-2017"
