    },
    {
      "tipe": "PENJELASAN_PASAL",
      "label": "Pasal 34A",
      "bagian_dokumen": "PENJELASAN",
      "hierarki": "PENJELASAN > PASAL",
      "parent_bab": "BAB XV",
      "parent_bagian": "Bagian Ketiga",
      "parent_paragraf": "Paragraf 2",
      "parent_pasal_perubahan": "Pasal 175",
      "teks": "Yang dimaksud dengan rencana zonasi adalah rencana pengelolaan ruang laut yang telah ditetapkan sesuai ketentuan peraturan perundang-undangan di bidang pengelolaan wilayah pesisir dan pulau-pulau kecil sebelum Undang-Undang ini berlaku."
    },
    {
      "tipe": "PENJELASAN_PASAL",
      "label": "Pasal 35",
      "bagian_dokumen": "PENJELASAN",
      "hierarki": "PENJELASAN > PASAL",
      "parent_bab": "BAB XV",
      "parent_bagian": "Bagian Ketiga",
      "parent_paragraf": "Paragraf 2",
      "parent_pasal_perubahan": "Pasal 175",
      "teks": "Pengendalian pemanfaatan ruang dimaksudkan agar pemanfaatan ruang dilakukan sesuai dengan rencana tata ruang."
    },
